import {useEffect,useRef,useState} from 'react';

import {Activity,ArrowDown,ArrowRight,ArrowUpRight,BarChart3,Bell,Bike,Check,ChevronRight,CircleHelp,Clock,CloudSun,Compass,Copy,Flag,Gauge,History,LayoutDashboard,Map,MapPin,Menu,MessageCircle,Navigation,Pause,Play,Plus,Radio,Route,Settings,ShieldCheck,Siren,Sparkles,TriangleAlert,UserRound,Users,Wifi,WifiOff,X,LogOut} from 'lucide-react';

import {Tabs,TabsList,TabsTrigger} from '@/components/ui/tabs';

import {AlertDialog,AlertDialogContent,AlertDialogTitle,AlertDialogDescription} from '@/components/ui/alert-dialog';

import {useRides} from '@/lib/store';

import {configured,demoMode,call,logout} from '@/lib/firebase';

import {Modal,CreateForm,JoinForm,ProfileForm,LoginForm,Field,Choice} from '@/components/forms';

import {RideDetail} from '@/components/ride-detail';

import {RideMap} from '@/components/ride-map';

import {CommandMap} from '@/components/command-map';

import {RideMapSwitch} from '@/components/ride-map-switch';

import {Analytics,CheckIn,HazardForm,HazardList,Health,PrivacyCenter,RideReport,RiderInspector,WeatherPanel} from '@/components/platform-panels';

import {Communication} from '@/components/communication';

import {awareness,currentPosition,distance} from '@/services/location';

